describe('Breadcrumb Navigation - Current Location Display', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should display correct breadcrumb trail for home page', () => {
    // Verify home page is loaded
    cy.get('[data-testid="home-page"]').should('be.visible');

    // Verify breadcrumb container exists
    cy.get('[data-testid="breadcrumb-container"]').should('be.visible');

    // Verify breadcrumb items are present
    cy.get('[data-testid="breadcrumb-item"]').should('have.length', 3);

    // Verify first breadcrumb item is 'Home'
    cy.get('[data-testid="breadcrumb-item"]').eq(0).should('contain', 'Home');

    // Verify second breadcrumb item is 'Category'
    cy.get('[data-testid="breadcrumb-item"]').eq(1).should('contain', 'Category');

    // Verify third breadcrumb item is 'Subcategory'
    cy.get('[data-testid="breadcrumb-item"]').eq(2).should('contain', 'Subcategory');

    // Verify breadcrumb separator
    cy.get('[data-testid="breadcrumb-separator"]').should('be.visible');

    // Verify breadcrumb link for 'Home'
    cy.get('[data-testid="breadcrumb-link"]').eq(0).should('have.attr', 'href', '/');

    // Verify breadcrumb link for 'Category'
    cy.get('[data-testid="breadcrumb-link"]').eq(1).should('have.attr', 'href', '/category');

    // Verify breadcrumb link for 'Subcategory'
    cy.get('[data-testid="breadcrumb-link"]').eq(2).should('have.attr', 'href', '/category/subcategory');
  });

  it('should update breadcrumb trail when navigating to a different page', () => {
    // Navigate to a different page
    cy.get('[data-testid="category-link"]').click();

    // Verify breadcrumb container still exists
    cy.get('[data-testid="breadcrumb-container"]').should('be.visible');

    // Verify breadcrumb items are updated
    cy.get('[data-testid="breadcrumb-item"]').should('have.length', 3);

    // Verify first breadcrumb item is 'Category'
    cy.get('[data-testid="breadcrumb-item"]').eq(0).should('contain', 'Category');

    // Verify second breadcrumb item is 'Subcategory'
    cy.get('[data-testid="breadcrumb-item"]').eq(1).should('contain', 'Subcategory');

    // Verify third breadcrumb item is 'Product'
    cy.get('[data-testid="breadcrumb-item"]').eq(2).should('contain', 'Product');

    // Verify breadcrumb separator
    cy.get('[data-testid="breadcrumb-separator"]').should('be.visible');

    // Verify breadcrumb link for 'Category'
    cy.get('[data-testid="breadcrumb-link"]').eq(0).should('have.attr', 'href', '/category');

    // Verify breadcrumb link for 'Subcategory'
    cy.get('[data-testid="breadcrumb-link"]').eq(1).should('have.attr', 'href', '/category/subcategory');

    // Verify breadcrumb link for 'Product'
    cy.get('[data-testid="breadcrumb-link"]').eq(2).should('have.attr', 'href', '/category/subcategory/product');
  });
});
